package com.example.spring_blog.reply;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Modifying;import org.springframework.data.jpa.repository.Query;import org.springframework.data.repository.query.Param;import java.util.List;public interface ReplyJpaRepository extends JpaRepository<Reply, Long> {    @Query("select r from Reply r join fetch r.user where r.board.id = :boardId order by r.id asc")    List<Reply> findAllByBoardJoinUser(@Param("boardId") Long boardId);    @Modifying    @Query("delete from Reply r where r.board.id = :boardId")    void deleteBoardId(@Param("boardId") Long boardId);}